    @Test
    void tourismTaxCountsMultipleGuests() {
        Reservation june = book(101, "2027-06-10", "2027-06-13", RatePlan.STANDARD);
        Guest multiGuest = new Guest("Ana Silva", "ana@example.com", "123.456.789-00");
        Reservation withThree = service.create(new NewReservation(
                102, multiGuest, LocalDate.parse("2027-06-11"), LocalDate.parse("2027-06-12"), 3, RatePlan.STANDARD));
        service.confirm(june.id());
        service.confirm(withThree.id());

        String csv = new hotel.reports.TourismTaxReport(store).generate(YearMonth.of(2027, 6));

        // 1 guest × 3 nights × 4.50 = 13.50
        // 3 guests × 1 night × 4.50 = 13.50
        assertEquals("""
                Pousada Maré Alta,tourism-tax,2027-06
                reservation,room,check_in,check_out,guests,nights,tax
                6,101,2027-06-10,2027-06-13,1,3,13.50
                7,102,2027-06-11,2027-06-12,3,1,13.50
                total,27.00
                """, csv);
    }

